class Solution {
  private int[] demand;
  private int n;
  private java.util.HashMap<Long, int[]> memo = new java.util.HashMap<>();

  // returns {served cars from index i on, minimal maximum waiting among them}
  private int[] solve(int i, int f0, int f1, int r0, int r1) {
    if (i == n) return new int[] {0, 0};
    long key = ((((long) i * 64 + f0) * 64 + f1) * 64 + r0) * 64 + r1;
    int[] cached = memo.get(key);
    if (cached != null) return cached;
    int[] best = {0, 0};
    int d = demand[i];
    for (int j = 0; j < 2; j++) {
      int fuel = j == 0 ? f0 : f1;
      if (fuel < d) continue;
      int rel = j == 0 ? r0 : r1, other = j == 0 ? r1 : r0;
      int wait = Math.max(0, rel);
      int newOther = Math.max(0, other - wait);
      int[] sub =
          j == 0 ? solve(i + 1, f0 - d, f1, d, newOther) : solve(i + 1, f0, f1 - d, newOther, d);
      int served = 1 + sub[0], maxWait = Math.max(wait, sub[1]);
      if (served > best[0] || (served == best[0] && maxWait < best[1]))
        best = new int[] {served, maxWait};
    }
    memo.put(key, best);
    return best;
  }

  public int minMaxWaitingTime(int[] demand, int[] fuel) {
    this.demand = demand;
    n = demand.length;
    int[] res = solve(0, fuel[0], fuel[1], 0, 0);
    return res[0] == 0 ? -1 : res[1];
  }
}
